/* ==UserStyle==
@name           00_Z All Wesite Variables
@namespace      github.com/seenukarthi/Stylus
@version        1.0.0
@description    This Variables for most of the website.
@author         Karthikeyan Vaithilingam

var text vknDefaultFontFamily "Default Font Family" "'Ubuntu Mono','OperatorMonoLig Nerd Font', 'Noto Sans Mono', Helvetica Neue, Helvetica, Verdana, sans-serif"
var text vknMonoFontFamily "Mono Font Family" "'Liga NotoSansMono', 'LigaLekton Nerd Font', 'Consolig Nerd Font', 'Menlo', 'DejaVu Sans Mono', 'Liberation Mono', 'Consolas', 'Ubuntu Mono', 'Courier New', 'andale mono', 'lucida console', monospace"
==/UserStyle== */
@-moz-document regexp("https?://.*"),
url-prefix("moz-extension://"),
url-prefix("chrome-extension://") {
    :root {
        --vknFallbackDefaultFont: 'Ubuntu', 'Fira Sans', 'OperatorMonoLig Nerd Font', 'Noto Sans Mono', Helvetica Neue, Helvetica, Verdana, sans-serif;
        --vknFallbackMonoFontFamily: 'Ubuntu Sans Mono Nerd Font', 'Consolig Nerd Font', 'Liga NotoSansMono', 'LigaLekton Nerd Font', 'OperatorMonoLig Nerd Font', 'Menlo', 'DejaVu Sans Mono', 'Liberation Mono', 'Consolas', 'Ubuntu Mono', 'Courier New', 'andale mono', 'lucida console', monospace;

        --vknDefaultFontFamily: 'Ubuntu Sans', var(--vknFallbackDefaultFont);
        --vknMonoFontFamily: 'MapleMono Nerd Font', var(--vknFallbackMonoFontFamily);
        --vknDefaultFontSize: 11px;
        --vknMonoFontWeight: 300;
        --vknMonoFontSize: inherit;
    }
}
